import{_ as a}from"./chunks/mcp_setup_window.Bmk85iqH.js";import{_ as o,C as n,o as r,c as i,E as s,a2 as l}from"./chunks/framework.BEADHO7-.js";const w=JSON.parse(`{"title":"Let AI Build the Effect","description":"An MCP server for DaVinci Resolve that lets AI clients such as Claude and Codex look up Mug Typography's features and Lua scripting API, write scripts, and verify them in a simulator.","frontmatter":{"title":"Let AI Build the Effect","description":"An MCP server for DaVinci Resolve that lets AI clients such as Claude and Codex look up Mug Typography's features and Lua scripting API, write scripts, and verify them in a simulator.","pageClass":"feature-guide","aside":false,"head":[["link",{"rel":"alternate","hreflang":"ja","href":"https://mug-lab-3.github.io/mug-typography-docs/features/feature-mcp.html"}],["link",{"rel":"alternate","hreflang":"en","href":"https://mug-lab-3.github.io/mug-typography-docs/en/features/feature-mcp.html"}],["link",{"rel":"alternate","hreflang":"x-default","href":"https://mug-lab-3.github.io/mug-typography-docs/features/feature-mcp.html"}],["link",{"rel":"canonical","href":"https://mug-lab-3.github.io/mug-typography-docs/en/features/feature-mcp.html"}],["meta",{"property":"og:type","content":"website"}],["meta",{"property":"og:site_name","content":"Mug Typography Manual"}],["meta",{"property":"og:locale","content":"en_US"}],["meta",{"property":"og:title","content":"Let AI Build the Effect | Mug Typography Manual"}],["meta",{"property":"og:description","content":"An MCP server for DaVinci Resolve that lets AI clients such as Claude and Codex look up Mug Typography's features and Lua scripting API, write scripts, and verify them in a simulator."}],["meta",{"property":"og:url","content":"https://mug-lab-3.github.io/mug-typography-docs/en/features/feature-mcp.html"}],["meta",{"property":"og:image","content":"https://mug-lab-3.github.io/mug-typography-docs/image/social-card.png"}],["meta",{"property":"og:image:type","content":"image/png"}],["meta",{"property":"og:image:width","content":"1200"}],["meta",{"property":"og:image:height","content":"630"}],["meta",{"property":"og:image:alt","content":"Mug Typography Manual"}],["meta",{"name":"twitter:card","content":"summary_large_image"}],["meta",{"name":"twitter:site","content":"@MugLab3"}],["meta",{"name":"twitter:title","content":"Let AI Build the Effect | Mug Typography Manual"}],["meta",{"name":"twitter:description","content":"An MCP server for DaVinci Resolve that lets AI clients such as Claude and Codex look up Mug Typography's features and Lua scripting API, write scripts, and verify them in a simulator."}],["meta",{"name":"twitter:image","content":"https://mug-lab-3.github.io/mug-typography-docs/image/social-card.png"}],["meta",{"name":"twitter:image:alt","content":"Mug Typography Manual"}]]},"headers":[],"relativePath":"en/features/feature-mcp.md","filePath":"en/features/feature-mcp.md"}`),p={name:"en/features/feature-mcp.md"};function g(c,e,u,h,d,m){const t=n("FeatureHero");return r(),i("div",null,[s(t,{language:"en",eyebrow:"MUG TYPOGRAPHY MCP",title:"Let AI Build the Effect",description:"AI clients such as Claude and Codex can look up Mug Typography's features and Lua scripting API on their own, write a script, and test-run it before handing it to you. You no longer need to paste the reference manual into every chat, and you get working scripts with far fewer errors.",image:"/image/mcp_hero_en.svg","image-alt":"Diagram showing how an AI client looks up documentation via Mug Typography MCP, verifies the script, and applies the effect in DaVinci Resolve","detail-link":"/en/features/feature-scripting","detail-label":"Lua Scripting Guide","point-one":"The AI looks things up itself","point-two":"Checks the script it writes","point-three":"Six AI clients supported","is-new":!0}),e[0]||(e[0]=l('<h2 id="how-to-use" tabindex="-1">How to Use <a class="header-anchor" href="#how-to-use" aria-label="Permalink to &quot;How to Use&quot;">​</a></h2><ol><li><p>Download the MCP archive for your OS from the same <a href="https://muglab3.booth.pm/items/8339678" target="_blank" rel="noreferrer">BOOTH page</a> as the plugin, extract it, and run the installer inside.</p><ul><li>Windows: <code>MugTypographyMCP-Setup.exe</code></li><li>macOS: <code>MugTypographyMCP.pkg</code></li></ul><p>When installation finishes, it automatically registers itself with the supported AI clients it finds.</p></li><li><p>Your OS may show a security warning when you open the installer. If it does, proceed as follows:</p><ul><li><strong>Windows</strong>: If &quot;Windows protected your PC&quot; appears, click <strong>More info</strong>, then click <strong>Run anyway</strong>.</li><li><strong>macOS</strong>: If macOS says it cannot verify the package, close the dialog and open <strong>System Settings &gt; Privacy &amp; Security</strong>. Scroll down and click <strong>Open Anyway</strong> next to <code>MugTypographyMCP.pkg</code> (or Control-click the package and choose <strong>Open</strong>).</li></ul></li><li><p>Restart your AI client, or reload its MCP servers.</p></li><li><p>Ask the AI for the effect you want.</p><blockquote><p>Write a Mug Typography Lua script where the letters of &quot;HELLO&quot; drop in one by one from above and bounce.</p></blockquote></li></ol><h2 id="what-it-does" tabindex="-1">What It Does <a class="header-anchor" href="#what-it-does" aria-label="Permalink to &quot;What It Does&quot;">​</a></h2><p>With <strong>Mug Typography MCP</strong> installed, your AI client can look up everything it needs about Mug Typography and test the scripts it writes on its own.</p><ul><li><strong>Looks up documentation and samples</strong>: The AI reads the plugin&#39;s features, Inspector parameters, Lua scripting API, and bundled sample scripts whenever needed, so you do not have to paste the reference manual into your prompt every time.</li><li><strong>Resolves font names</strong>: It queries the exact font list available in the plugin, so fonts can be selected accurately by their display names.</li><li><strong>Verifies generated scripts</strong>: It runs the Lua script in the built-in simulator to check for runtime errors, off-screen characters, sudden frame-to-frame jumps, and parameter changes, and can render a single-frame preview image.</li></ul><p>The preview image is a placement guide only. Always check the final look in DaVinci Resolve.</p><h2 id="about-operating-davinci-resolve" tabindex="-1">About Operating DaVinci Resolve <a class="header-anchor" href="#about-operating-davinci-resolve" aria-label="Permalink to &quot;About Operating DaVinci Resolve&quot;">​</a></h2><p>Mug Typography MCP does not control DaVinci Resolve directly. Copy the generated Lua script and load it into the plugin using <strong>Paste Script</strong> in the Inspector.</p><p>If you also use a DaVinci Resolve MCP server in your AI client, you can ask the AI to add the node and apply <strong>Script Text</strong> directly to the current timeline. If you only want a script, you do not need a Resolve MCP.</p><h2 id="requirements" tabindex="-1">Requirements <a class="header-anchor" href="#requirements" aria-label="Permalink to &quot;Requirements&quot;">​</a></h2><ul><li>Windows 11 (64-bit), or macOS 13.3 or later (Apple Silicon only)</li><li>DaVinci Resolve 21 with Mug Typography installed</li><li>One of these AI clients: Claude Desktop, Codex, Cursor, VS Code (GitHub Copilot), Gemini CLI, Antigravity</li></ul><h2 id="checking-and-removing-the-registration" tabindex="-1">Checking and Removing the Registration <a class="header-anchor" href="#checking-and-removing-the-registration" aria-label="Permalink to &quot;Checking and Removing the Registration&quot;">​</a></h2><p><img src="'+a+'" alt="The Mug Typography MCP window, showing all six AI clients it found as registered"></p><p>You can check the registration status in this window:</p><ul><li>Windows: <strong>Mug Typography &gt; Mug Typography MCP</strong> in the Start menu</li><li>macOS: <code>MugTypographyMCP</code> in <code>~/Applications</code> (the <code>Applications</code> folder inside your home folder)</li></ul><p>The window shows the status of each supported AI client. <strong>Register all</strong> registers every client at once, and <strong>Unregister all</strong> removes them all. <strong>Check the connection</strong> calls every tool once and opens a report showing what the AI sends and what comes back.</p><h2 id="updating-and-uninstalling" tabindex="-1">Updating and Uninstalling <a class="header-anchor" href="#updating-and-uninstalling" aria-label="Permalink to &quot;Updating and Uninstalling&quot;">​</a></h2><ul><li><strong>Updating</strong>: Run the newer installer. It replaces the program and updates the registration.</li><li><strong>Uninstalling</strong>: <ul><li>Windows: Use <strong>Mug Typography &gt; Uninstall Mug Typography MCP</strong> in the Start menu, or <strong>Settings &gt; Apps</strong>. This also removes the registration from your AI clients.</li><li>macOS: Open <code>MugTypographyMCP</code> and click <strong>Unregister all</strong> to remove the registration, then move <code>~/Applications/MugTypographyMCP.app</code> to the Trash.</li></ul></li></ul><h2 id="if-it-does-not-work" tabindex="-1">If It Does Not Work <a class="header-anchor" href="#if-it-does-not-work" aria-label="Permalink to &quot;If It Does Not Work&quot;">​</a></h2><ul><li><strong>The AI does not use Mug Typography&#39;s features</strong> - Restart the AI client or reload its MCP servers. <strong>Check the connection</strong> in the registration window also verifies whether the tools can be called properly.</li><li><strong>The window shows &quot;Another copy&quot;</strong> - A copy installed in another folder is currently registered with an AI client. Click <strong>Register all</strong> to replace it with the current installation.</li></ul>',20))])}const M=o(p,[["render",g]]);export{w as __pageData,M as default};
